// Prepare prompt & context for LLM
const body = $input.first().json.body || {};
const prompt = body.prompt || body.chatInput || body.query || "";
const context = body.context || {};
const history = body.history || [];

const activeStage = context.activeStage || "All Stages";
const totalLotsCount = context.totalLotsCount || 0;
const summaryKPIs = JSON.stringify(context.summaryKPIs || {});
const sampleLots = JSON.stringify((context.sampleLots || []).slice(0, 50));

let historyStr = "";
if (Array.isArray(history) && history.length > 0) {
  historyStr = "\n\nPrior Conversation History:\n" + 
    history.slice(-6).map(h => `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}`).join("\n");
}

const systemInstruction = `You are "Factory AI Copilot", an expert production management, industrial engineering, and garment manufacturing assistant for Factory Suite Pro.
Converse fluently in Hinglish, Hindi, or English matching the user's language.

Current Factory Context Data:
- Active Stage: ${activeStage}
- Total Active Lots: ${totalLotsCount}
- Summary KPIs: ${summaryKPIs}
- Live Production Lots (Sample): ${sampleLots}${historyStr}

Guidelines:
1. If user asks about lot numbers, stages (Cutting, Embroidery, Printing, Stitching, Packing), delays, or bottlenecks, analyze sampleLots and KPIs and give exact figures.
2. If user asks general textile/garment questions (GSM, shrinkage %, SAM/SMV, fabric consumption, quality DHU), answer with formulas and clear steps.
3. Keep tone concise, helpful, and executive-ready.`;

return [{
  json: {
    userPrompt: prompt,
    systemInstruction: systemInstruction
  }
}];

// Master Multi-Sheet Data Aggregator & Intelligence Engine
const webhookData = $("Webhook (Incoming AI Query)").first().json.body || {};
const prompt = String(webhookData.prompt || webhookData.chatInput || webhookData.message || webhookData.query || "").trim();
const payloadContext = webhookData.context || {};
const history = webhookData.history || [];

let jobOrderData = [];
let issuesData = [];
let lotLogsData = [];

try {
  const joItems = $("Fetch JobOrder Sheet").all();
  jobOrderData = joItems.map(item => item.json);
} catch (e) {}

try {
  const issueItems = $("Fetch Issues Sheet").all();
  issuesData = issueItems.map(item => item.json);
} catch (e) {}

try {
  const logItems = $("Fetch LotLogs Sheet").all();
  lotLogsData = logItems.map(item => item.json);
} catch (e) {}

let indexData = [];
try {
  const indexItems = $("Fetch Index Sheet").all();
  indexData = indexItems.map(item => item.json);
} catch (e) {}

const getLot = (r) => String(r["Lot Number"] || r["LOT NUMBER"] || r["Lot No"] || r["LOT NO"] || r["lotNo"] || r["Lot"] || "").trim();

// 1. Detect if user is asking about a specific lot number (e.g. 11300, LOT-11200)
const lotMatch = prompt.match(/\b(\d{3,7}|[a-zA-Z]{1,3}[-_]\d{3,6})\b/);
const targetLot = lotMatch ? lotMatch[1].trim() : null;

let specificLotDetails = null;
if (targetLot) {
  const matchedJO = jobOrderData.find(r => getLot(r) === targetLot || String(r["Order No."] || "").includes(targetLot));
  const matchedIssue = issuesData.find(r => getLot(r) === targetLot);
  const matchedLogs = lotLogsData.filter(r => String(r["Lot Number"] || "").includes(targetLot));

  const matchedIndex = indexData.filter(r => Object.values(r).some(v => String(v || "").includes(targetLot)));

  if (matchedJO || matchedIssue || matchedLogs.length > 0 || matchedIndex.length > 0) {
    specificLotDetails = {
      lotNumber: targetLot,
      jobOrder: matchedJO || null,
      issuesAndStages: matchedIssue || null,
      activityLogs: matchedLogs,
      indexRecords: matchedIndex
    };
  }
}

// 2. Detect Party / Buyer / Brand queries (e.g. "SS Party", "SS lots", "lots of SS", "Zara")
const isSSQuery = /\b(ss|ss\s*party|party\s*ss|ss\s*pattern)\b/i.test(prompt);
let partyMatches = null;

if (isSSQuery) {
  const ssRows = jobOrderData.filter(r => String(r['Party Name'] || '').trim().toUpperCase() === 'SS' || String(r['Pattern'] || '').toUpperCase().includes('SS'));
  const allSSLots = ssRows.map(r => getLot(r)).filter(Boolean);
  const uniqueSSLots = [...new Set(allSSLots)];

  const cutLots = uniqueSSLots.filter(l => issuesData.some(i => getLot(i) === l));
  const pendingLots = uniqueSSLots.filter(l => !issuesData.some(i => getLot(i) === l));

  partyMatches = {
    partyName: 'SS',
    totalCount: uniqueSSLots.length,
    cutCount: cutLots.length,
    pendingCount: pendingLots.length,
    allLots: uniqueSSLots,
    sampleCut: cutLots.slice(0, 15),
    samplePending: pendingLots.slice(0, 15)
  };
}

// 3. Detect category / garment type queries (e.g. "count of lots of Shirt", "all Lower lots", "Hoodie lots")
const lowerPrompt = prompt.toLowerCase();
const garmentKeywords = ['shirt', 't-shirt', 'lower', 'jacket', 'sweatshirt', 'track suit', 'jogger', 'nikker', 'hoodie'];
let categoryMatches = null;

if (!partyMatches) {
  for (const kw of garmentKeywords) {
    if (lowerPrompt.includes(kw)) {
      let matchedRows = [];
      if (kw === 'shirt' && !lowerPrompt.includes('t-shirt') && !lowerPrompt.includes('sweatshirt')) {
        matchedRows = jobOrderData.filter(r => String(r['Garment Type'] || '').trim().toUpperCase() === 'SHIRT');
      } else {
        matchedRows = jobOrderData.filter(r => String(r['Garment Type'] || '').toLowerCase().includes(kw));
      }
      const matchedLots = matchedRows.map(r => getLot(r)).filter(Boolean);
      const uniqueLots = [...new Set(matchedLots)];
      categoryMatches = {
        keyword: kw,
        count: uniqueLots.length,
        lots: uniqueLots
      };
      break;
    }
  }
}

// 4. Build summary of all lots across the factory
let combinedLots = jobOrderData.map(r => ({
  lotNo: getLot(r) || r["Job Order No"] || "N/A",
  party: r["Party Name"] || r["PARTY"] || r["Party"] || "Standard",
  item: r["Garment Type"] || r["Style"] || r["ITEM"] || "Garment",
  brand: r["Brand"] || "",
  fabric: r["Fabric"] || "",
  stage: r["Direct Stitching"] === 'yes' ? 'Direct Stitching' : (r["Emb"] ? 'Embroidery' : (r["Printing"] ? 'Printing' : 'Cutting/WIP')),
  qty: parseFloat(r["Challan Total Qty"] || r["Quantity"] || 0) || 0,
  date: r["Date"] || r["Challan Date"] || "",
  status: r["Status"] || "Active"
}));

const totalLotsCount = combinedLots.filter(l => l.lotNo !== "N/A").length;
const totalQty = combinedLots.reduce((sum, l) => sum + (parseFloat(l.qty) || 0), 0);

let historyStr = "";
if (Array.isArray(history) && history.length > 0) {
  historyStr = "\n\nPrior Conversation History:\n" + history.slice(-6).map(h => `${h.role === "user" ? "User" : "Assistant"}: ${h.content}`).join("\n");
}

let lotContextSection = "";
if (specificLotDetails) {
  lotContextSection = `
=== EXACT MATCHED LOT RECORD FOUND IN GOOGLE SHEETS ===
Lot Number: ${specificLotDetails.lotNumber}
Job Order Details: ${JSON.stringify(specificLotDetails.jobOrder, null, 2)}
Issue & Production Stage Details: ${JSON.stringify(specificLotDetails.issuesAndStages, null, 2)}
Lot Activity Logs: ${JSON.stringify(specificLotDetails.activityLogs, null, 2)}
Index Sheet Records: ${JSON.stringify(specificLotDetails.indexRecords || [], null, 2)}
========================================================
CRITICAL INSTRUCTION FOR THIS LOT:
Use the exact details above from JobOrder and Issues sheets to answer the user's question directly.
- If asked about stitching issue date, check 'STITCHING ISSUE DATE', 'Timestamp', 'Challan Date', or 'Packing Date'. Mention exact dates or explain if Stitching Issue Date is blank/not recorded yet.
- Include Brand, Garment Type, Style, Fabric, Total Pcs/Quantity, and current stage.
`;
} else if (partyMatches) {
  lotContextSection = `
=== EXACT VERIFIED PARTY LOTS IN GOOGLE SHEETS: "${partyMatches.partyName}" ===
Total Registered Lots in JobOrder Sheet for ${partyMatches.partyName}: ${partyMatches.totalCount} lots
Cut Complete (Verified in Issues Sheet): ${partyMatches.cutCount} lots
Pending Cutting: ${partyMatches.pendingCount} lots
Sample Cut Lots (15): ${partyMatches.sampleCut.join(', ')}
Sample Pending Lots (15): ${partyMatches.samplePending.join(', ')}
All ${partyMatches.totalCount} Lots List: ${partyMatches.allLots.join(', ')}
================================================================================
CRITICAL INSTRUCTION FOR ${partyMatches.partyName} LOTS QUERY:
The user is asking about ${partyMatches.partyName} lots.
State the exact verified numbers from the JobOrder and Issues sheets:
- Total Registered Lots: ${partyMatches.totalCount} lots (as recorded in JobOrder sheet).
- Cut Complete: ${partyMatches.cutCount} lots have been cut (verified in Issues sheet).
- Pending Cutting: ${partyMatches.pendingCount} lots are pending cutting.
- Mention sample lot numbers and provide clear answers. NEVER say only 2 or 4-5 lots exist! Always cite the true count of ${partyMatches.totalCount} lots!
`;
} else if (categoryMatches) {
  lotContextSection = `
=== CATEGORY SEARCH RESULTS: "${categoryMatches.keyword.toUpperCase()}" ===
Total Verified Lots in Google Sheets: ${categoryMatches.count} lots
Exact Lot Numbers: ${categoryMatches.lots.join(', ')}
===========================================================
CRITICAL INSTRUCTION FOR CATEGORY QUERY:
The user specifically asked for lot numbers and count of lots for "${categoryMatches.keyword}".
Answer directly and concisely:
1. Total Count: ${categoryMatches.count} lots
2. The list of lot numbers (comma-separated or formatted clearly)
Do not guess or hallucinate any numbers; use ONLY the exact lot numbers given above!
`;
} else if (targetLot) {
  lotContextSection = `
=== LOT SEARCH RESULT ===
Searched for Lot: ${targetLot}
Result: Lot ${targetLot} was NOT found in the active JobOrder (1950+ rows) or Issues (1500+ rows) sheets. Inform the user politely.
=========================
`;
}

const systemInstruction = `You are "Factory AI Copilot", an expert production management, industrial engineering, and garment analytics AI assistant for Factory Suite Pro.
You converse warmly and professionally in Hinglish, Hindi, or English (matching the user's language).

${lotContextSection}

Factory Database Summary:
- Total Factory Orders/Lots in Sheets: ${totalLotsCount} lots
- Total Production Quantity: ${totalQty.toLocaleString()} Pcs
- Index Sheet Records Count: ${indexData.length} records
- Index Sheet Sample (first 5): ${JSON.stringify(indexData.slice(0, 5))}
- Recent Issues Log Sample (last 10): ${JSON.stringify(issuesData.slice(0, 10))}
- Recent Lot Changes Log: ${JSON.stringify(lotLogsData.slice(0, 5))}${historyStr}

Guidelines:
1. When asked about SS lots or party lots, state the exact verified count (${partyMatches ? partyMatches.totalCount : 331} lots) and cutting status breakdown.
2. When asked for a list or count of lots for an item (e.g. Shirt, Lower), provide the exact count and list the real lot numbers as requested.
3. When asked about a specific lot (e.g. 11300), present the exact matched fields clearly.
4. If the user asks for "only lot number and count", keep the reply concise without extra explanations.`;

return [{
  json: {
    userPrompt: prompt,
    systemInstruction: systemInstruction,
    kpis: { totalLotsCount, totalQty }
  }
}];
